// Claude's review tests for A14 (import a HAR file). agy: do not edit this file.
import { expect, test } from '@playwright/test';
import { emptyState, newProject, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

function harFile(origin: string): Buffer {
  const e = (url: string, type: string, mime: string, text: string) => ({
    startedDateTime: '2026-11-09T10:00:00.000Z',
    _resourceType: type,
    request: { method: 'GET', url: `${origin}${url}`, headers: [] },
    response: { status: 200, headers: [{ name: 'content-type', value: mime }], content: { mimeType: mime, text } },
  });
  return Buffer.from(JSON.stringify({
    log: {
      version: '1.2',
      entries: [
        e('/api/goals', 'fetch', 'application/json', '{"from":"har"}'),
        e('/api/team', 'xhr', 'application/json', '{"team":[]}'),
        e('/logo.png', 'image', 'image/png', 'AA=='),
      ],
    },
  }));
}

test('a HAR file becomes a scenario that answers the page', async () => {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [newProject('p1', fixture.origin)] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  try {
    await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('import').setInputFiles({ name: 'session.har', mimeType: 'application/json', buffer: harFile(fixture.origin) });
    await expect(panel.getByTestId('import-choice')).toBeVisible();
    await panel.getByTestId('import-replace').click();
    await expect(panel.getByTestId('import-summary')).toHaveText('2 mocks from 2 calls (1 skipped)');

    const p = (await readState()).projects[0]!;
    expect(p.id).toBe('p1');
    expect(p.scenarios.map((s) => s.name)).toEqual(['Default', 'HAR session.har']);
    expect(p.activeScenarioId).toBe(p.scenarios[1]!.id);

    await page.reload();
    expect(await page.evaluate(async () => (await fetch('/api/goals')).text())).toBe('{"from":"har"}');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Add keeps my scenarios and adds the HAR one', async () => {
  const mine = newProject('p1', fixture.origin);
  mine.scenarios.push({ id: 'keep', name: 'Mine', mocks: [] });
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [mine] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  try {
    await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('import').setInputFiles({ name: 'b.har', mimeType: 'application/json', buffer: harFile(fixture.origin) });
    await panel.getByTestId('import-add').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios.map((s) => s.name)).toEqual(['Default', 'Mine', 'HAR b.har']);
  } finally {
    await panel.close();
    await page.close();
  }
});
